// --- #1 brick bounce ------------------------------------------------------

// A brick with friendly numbers for the collision math.
function brick() {
  return { x: 100, y: 100, w: 72, h: 20, alive: true, points: 10 };
}

// A ball centred at (x, y) that on the previous physics step sat at (px, py).
function ball(x, y, px, py, vx, vy, r = 7) {
  return { x, y, px, py, r, vx, vy };
}

// Move helpers ------------------------------------------------------------

// Test the previous-position fields directly: `step()` records them, and
// `brickHit()` reads them to sweep the ball's travel between two frames.
function withPrev(ball, px, py) {
  return { ...ball, prevX: px, prevY: py };
}

// #1 per-face: ball below a brick, moving up => it hits the BOTTOM face,
// vy flips sign, vx is untouched and the ball is pushed out (no longer
// overlapping the brick).
test('brickHit: bottom-face hit flips vy up, keeps vx, pushes out', () => {
  const b = brick();
  const ballState = withPrev(ball(136, 115, 136, 140, 0, -100), 136, 140);
  const hits = brickHit(ballState, [b]);

  assert.equal(hits.length, 1);
  assert.equal(b.alive, false);
  assert.equal(Math.sign(ballState.vy), DOWN, 'vy should bounce downward');
  assert.equal(ballState.vx, 0, 'vx must be untouched on a y hit');
  assert.equal(collides(ballState, b), false, 'ball must be pushed out');
});

// #1 per-face: ball to the left of a brick, moving right => SIDE (left-face)
// hit: vx flips, vy left as-is, ball pushed out.
test('brickHit: side hit flips vx, keeps vy, pushes out', () => {
  const b = brick();
  const ballState = withPrev(ball(95, 110, 80, 110, 50, 0), 80, 110);
  const hits = brickHit(ballState, [b]);

  assert.equal(hits.length, 1);
  assert.equal(b.alive, false);
  assert.equal(Math.sign(ballState.vx), -1, 'vx should flip to the left');
  assert.equal(ballState.vy, 0, 'vy must be untouched on an x hit');
  assert.equal(collides(ballState, b), false, 'ball must be pushed out');
});

// #1 corner: a diagonal hit into a corner flips BOTH components and pushes
// the ball out of overlap.
test('brickHit: diagonal corner hit flips both components', () => {
  const b = brick();
  // centred exactly on the brick's top-left corner => equal penetration on
  // both axes.
  const ballState = withPrev(ball(100, 100, 90, 130, 40, -40), 90, 130);
  const hits = brickHit(ballState, [b]);

  assert.equal(hits.length, 1);
  assert.equal(b.alive, false);
  assert.equal(ballState.vx, -40, 'vx should flip');
  assert.equal(ballState.vy, 40, 'vy should flip');
  assert.equal(collides(ballState, b), false, 'ball must be pushed out');
});

// #1 neighbours: two bricks sharing a seam (the 8 px gap) overlap the SAME
// 14 px ball in a single pass. The bounce must be applied exactly once: if
// vy changed twice it would cancel out and the ball would travel through.
test('brickHit: seam between two bricks bounces exactly once', () => {
  const a = { x: 100, y: 100, w: 72, h: 20, alive: true, points: 10 };
  const b = { x: 180, y: 100, w: 72, h: 20, alive: true, points: 10 };
  // Ball centred over the 8 px gap (x 172..180), moving up into both bricks.
  const ballState = withPrev(ball(176, 113, 176, 125, 0, -100), 176, 125);
  const hits = brickHit(ballState, [a, b]);

  assert.equal(hits.length, 2, 'both seam neighbours are hit');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  // Exactly one bounce: vy must have flipped sign once (it went in at UP and
  // must come back DOWN), not be cancelled back to UP.
  assert.equal(Math.sign(ballState.vy), DOWN, 'vy flipped exactly once');
  assert.equal(collides(ballState, a) || collides(ballState, b), false, 'pushed out');
});

// #1 push-out: the resolved ball must stop overlapping every brick it hit,
// otherwise the next frame re-detects the same collision and re-flips.
test('brickHit: ball is always repositioned outside the hit bricks', () => {
  for (let cy = 95; cy <= 125; cy += 5) {
    for (let cx = 95; cx <= 175; cx += 5) {
      const b = brick();
      const ballState = withPrev(ball(cx, cy, cx, cy + 20, 0, -60), cx, cy + 20);
      brickHit(ballState, [b]);
      assert.equal(collides(ballState, b), false, `still overlapping at x=${cx} y=${cy}`);
    }
  }
});

// #1 tunnelling: at high level the ball can move ~35 px in a single (capped)
// step while a brick is only 20 px high. The sweep between the previous and
// the current position must catch the brick so this frame doesn't skip it.
test('brickHit: sweep catches a ball that jumped over the brick', () => {
  const b = brick();
  // From just below the brick (y=135) to clearly above it (y=75): the whole
  // brick is crossed in one move.
  const ballState = withPrev(ball(136, 75, 136, 135, 0, -300), 136, 135);
  const hits = brickHit(ballState, [b]);

  assert.equal(hits.length, 1, 'fast move must still hit the brick');
  assert.equal(b.alive, false);
  // It was a bottom-face hit (approached from below): the ball must come
  // back DOWN and rest on the underside, not blow through.
  assert.equal(Math.sign(ballState.vy), DOWN);
  assert.equal(ballState.y, b.y + b.h + ballState.r, 'ball parked on the underside');
  assert.equal(collides(ballState, b), false);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

